export function getFood(grid            )         {
const rows=grid.length,cols=grid[0].length,q           =[],seen=new Set        ();for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)if(grid[r][c]==="*"){q.push([r,c,0]);seen.add(r+","+c);}for(let i=0;i<q.length;i++){const [r,c,d]=q[i];if(grid[r][c]==="#")return d;for(const [nr,nc] of [[r-1,c],[r+1,c],[r,c-1],[r,c+1]]){const key=nr+","+nc;if(nr>=0&&nc>=0&&nr<rows&&nc<cols&&grid[nr][nc]!=="X"&&!seen.has(key)){seen.add(key);q.push([nr,nc,d+1]);}}}return -1;
}

